//! Versioned full retained FX publication; never a recovery import.
use crate::{combat_visuals as v,state::Body};
use crate::flight_static_wire::{self as j,Value};
fn text(x:&Value)->Result<String,u32>{let s=x.text()?;if s.is_empty()||s.encode_utf16().count()>65_536{return Err(2);}Ok(s.to_owned())}
fn rgb<const N:usize>(x:&Value)->Result<[u8;N],u32>{let a=x.numbers::<N>()?;let mut o=[0;N];for(i,x)in a.iter().enumerate(){o[i]=u8::try_from(j::integer(*x)?).map_err(|_|2u32)?;}Ok(o)}
fn flash(x:&Value)->Result<v::FlashSpec,u32>{let mut p=x.object()?;let s=v::FlashSpec{length:p.get("length")?.number()?,spread:p.get("spread")?.number()?,minimum:p.get("particleSizeMin")?.number()?,range:p.get("particleSizeRange")?.number()?,duration:p.get("particleDuration")?.number()?,count:p.get("particleCount")?.int()?,color:rgb(p.get("particleColor")?)?};p.done()?;if s.count as usize>v::LIMIT||[s.length,s.spread,s.minimum,s.range,s.duration].iter().any(|n|*n<0.0){return Err(2);}Ok(s)}
fn smoke(x:&Value)->Result<v::SmokeSpec,u32>{let mut p=x.object()?;let s=v::SmokeSpec{minimum:p.get("particleSizeMin")?.number()?,range:p.get("particleSizeRange")?.number()?,cloud_count:p.get("cloudParticleCount")?.int()?,cloud_duration:p.get("cloudDuration")?.number()?,cloud_radius:p.get("cloudRadius")?.number()?,back_count:p.get("blowbackParticleCount")?.int()?,back_duration:p.get("blowbackDuration")?.number()?,back_length:p.get("blowbackLength")?.number()?,back_spread:p.get("blowbackSpread")?.number()?,color:rgb(p.get("particleColor")?)?};p.done()?;if s.cloud_count as usize+s.back_count as usize>v::LIMIT||[s.minimum,s.range,s.cloud_duration,s.cloud_radius,s.back_duration,s.back_length,s.back_spread].iter().any(|n|*n<0.0){return Err(2);}Ok(s)}
pub fn decode_meta(x:&Value)->Result<v::VisualMeta,u32>{let mut p=x.object()?;let overload_text=text(p.get("overloadText")?)?;let malfunction_text=text(p.get("malfunctionText")?)?;let fighter=p.get("fighter")?.bool()?;let surface=p.get("surface")?.bool()?;
    let mut engines=Vec::new();for x in p.get("engines")?.array()?{let mut e=x.object()?;let width=e.get("width")?.number()?;let color=e.get("color")?.numbers::<3>()?;e.done()?;if width<0.0||color.iter().any(|n|!(0.0..=255.0).contains(n)){return Err(2);}engines.push((width,color));}
    let mut mounts=Vec::new();for x in p.get("mounts")?.array()?{let mut m=x.object()?;let component=m.get("component")?.int()?;let slot=text(m.get("slot")?)?;let size=text(m.get("size")?)?;let name=text(m.get("name")?)?;
        if component==0||mounts.iter().any(|v:&v::MountMeta|v.component==component||v.slot==slot)||!matches!(size.as_str(),"small"|"medium"|"large"){return Err(8);}let below=m.get("below")?.bool()?;let beam=m.get("beam")?.bool()?;
        let sound=m.optional("sound").map(text).transpose()?;let intro=m.optional("intro").map(text).transpose()?;let loop_key=m.optional("loop").map(text).transpose()?;let muzzle_size=m.get("muzzleSize")?.number()?;
        let muzzle_color=m.optional("muzzleColor").map(rgb).transpose()?;let flash=m.optional("flash").map(flash).transpose()?;let smoke=m.optional("smoke").map(smoke).transpose()?;let projectile_length=m.optional("projectileLength").map(Value::number).transpose()?;
        let nozzle=m.optional("engine").map(|x|{let mut e=x.object()?;let n=e.get("nozzleOffset")?.number()?;for key in ["width","length"]{if e.get(key)?.number()?<0.0{return Err(2);}}let _: [u8;4]=rgb(e.get("color")?)?;e.optional("glowSizeMult").map(Value::number).transpose()?;e.optional("glowAlternateColor").map(rgb::<4>).transpose()?;e.done()?;Ok::<_,u32>(n)}).transpose()?;
        let trail=m.optional("trail").map(|x|->Result<v::TrailMeta,u32>{let mut t=x.object()?;let out=v::TrailMeta{duration:t.get("duration")?.number()?,width:t.get("baseWidth")?.number()?,widen:t.get("widenMult")?.number()?,min_seg:t.get("minSeg")?.number()?,offset:t.get("spawnOffset")?.number()?,color:rgb(t.get("color")?)?,glow:match t.get("blendMode")?.text()?{"NORMAL"=>false,"GLOW"=>true,_=>return Err(8)}};t.done()?;if out.duration<=0.0||out.width<0.0||out.min_seg<0.0{return Err(2);}Ok(out)}).transpose()?;
        let split_sound=m.optional("splitSound").map(text).transpose()?;let split_smoke=m.optional("splitSmoke").map(crate::visual_wire::smoke).transpose()?;m.done()?;if muzzle_size<0.0{return Err(2);}
        mounts.push(v::MountMeta{component,slot,size,name,below,beam,sound,intro,loop_key,muzzle_size,muzzle_color,flash,smoke,projectile_length,nozzle,trail,split_sound,split_smoke});}
    p.done()?;if engines.len()>v::LIMIT||mounts.len()>v::LIMIT{return Err(7);}Ok(v::VisualMeta{overload_text,malfunction_text,fighter,surface,engines,mounts})}
fn pad(x:&[f64],used:usize)->Result<(),u32>{if x.len()!=22||x.iter().any(|n|!n.is_finite())||x[used..].iter().any(|n|*n!=0.0){return Err(2);}Ok(())}
pub fn apply(tag:u32,x:&[f64],owner:&mut v::Owned,bodies:&[Body])->Result<(),u32>{if x.len()!=22{return Err(2);}if tag==183{pad(x,3)?;let length=j::integer(x[1])?as usize;let count=j::integer(x[2])?as usize;
        if x[0]!=1.0||owner.installed||owner.admission.is_some(){return Err(8);}if length==0||length>16_000_000||count!=bodies.len(){return Err(2);}owner.admission=Some(v::Admission{length,count,units:Vec::new()});return Ok(());}
    if tag==184{let at=j::integer(x[0])?as usize;let count=j::integer(x[1])?as usize;if count==0||count>20{return Err(2);}pad(x,2+count)?;let d=owner.admission.as_mut().ok_or(8u32)?;if at!=d.units.len()||at+count>d.length{return Err(8);}for n in &x[2..2+count]{d.units.push(u16::try_from(j::integer(*n)?).map_err(|_|2u32)?);}return Ok(());}
    if tag!=185{return Err(2);}pad(x,0)?;let d=owner.admission.as_ref().ok_or(8u32)?;if d.units.len()!=d.length||d.count!=bodies.len(){return Err(8);}let value=j::parse(&d.units)?;let mut p=value.object()?;if p.get("version")?.int()?!=1{return Err(8);}let values=p.get("ships")?.array()?;if values.len()!=bodies.len(){return Err(8);}let mut o=owner.clone();
    for x in values{let mut p=x.object()?;let id=p.get("id")?.int()?;let mut h=p.get("handle")?.object()?;let handle=crate::state::Handle{slot:h.get("slot")?.int()?,generation:h.get("generation")?.int()?};h.done()?;let b=bodies.iter().find(|b|b.id==id&&b.handle==handle).ok_or(4u32)?;let stable=text(p.get("stableId")?)?;let death=b.ship.as_ref().and_then(|s|s.combat.as_ref()).and_then(|s|s.death.as_ref()).ok_or(8u32)?;if String::from_utf16(&death.strings[3]).map_err(|_|2u32)?!=stable{return Err(8);}let meta=decode_meta(p.get("meta")?)?;p.done()?;o.admit(handle,stable,meta,bodies)?;}
    p.done()?;o.admission=None;o.installed=true;*owner=o;Ok(())}
fn flag(v:bool)->f64{v as u32 as f64}
fn string(o:&mut Vec<f64>,s:&str){let u:Vec<_>=s.encode_utf16().collect();o.push(u.len()as f64);o.extend(u.into_iter().map(|u|u as f64));}
fn optional_string(o:&mut Vec<f64>,s:Option<&str>){o.push(flag(s.is_some()));if let Some(s)=s{string(o,s);}}
fn optional(o:&mut Vec<f64>,s:Option<f64>){o.extend([flag(s.is_some()),s.unwrap_or(0.0)]);}
fn point(o:&mut Vec<f64>,s:Option<[f64;2]>){o.push(flag(s.is_some()));if let Some(s)=s{o.extend(s);}}
fn points(o:&mut Vec<f64>,p:&[[f64;2]]){o.push(p.len()as f64);o.extend(p.iter().flatten());}
fn record(o:&mut Vec<f64>,count:&mut usize,tag:u32,data:Vec<f64>){o.extend([tag as f64,data.len()as f64]);o.extend(data);*count+=1;}
fn audio_records(o:&mut Vec<f64>,n:&mut usize,v:&v::Owned){for a in &v.audio{let mut x=Vec::new();match a{v::Audio::Play{key,volume,rate,position,listener,maximum}=>{x.push(0.0);string(&mut x,key);x.extend([*volume,*rate]);point(&mut x,*position);point(&mut x,*listener);optional(&mut x,*maximum);},v::Audio::Loop{key,volume,active}=>{x.push(1.0);string(&mut x,key);x.extend([*volume,flag(*active)]);},v::Audio::Muffled(value)=>x.extend([2.0,flag(*value)])}record(o,n,14,x);}}
/// The same retained audio records, without constructing unrelated FX rows.
pub fn audio_words(v:&v::Owned)->Result<Vec<f64>,u32>{let mut o=vec![1.0,0.0];let mut n=0;let mut header=vec![v.audio_sequence,0.0];header.extend([0.0;12]);header.push(v.audio.len()as f64);record(&mut o,&mut n,1,header);audio_records(&mut o,&mut n,v);
    if v.audio.len()>v::LIMIT||o.len()>8_000_000||o.iter().any(|v|!v.is_finite()){return Err(7);}o[1]=n as f64;Ok(o)}
/// [version=1, recordCount, tag,length,...]. Mandatory tag1 certifies every
/// retained category count including genuine empty lists. Read-only and pure.
pub fn words(v:&v::Owned,bodies:&[Body])->Result<Vec<f64>,u32>{v.bounded()?;let mut o=vec![1.0,0.0];let mut n=0;let counts=[v.particles.len(),v.contrails.len(),v.debris.len(),v.explosions.len(),v.glows.len(),v.rays.len(),v.emp.len(),v.muzzles.len(),v.muzzle_particles.len(),v.ripples.len(),v.trails.len(),v.ships.len(),v.audio.len()];
    let mut header=vec![v.audio_sequence,v.shake];header.extend(counts.map(|c|c as f64));record(&mut o,&mut n,1,header);
    for p in &v.particles{let mut x=Vec::new();x.extend(p.position);x.extend(p.velocity);x.extend([p.life,p.max_life,p.size]);x.extend(p.color);x.extend([p.alpha,p.material as f64]);for f in p.optional{optional(&mut x,f);}record(&mut o,&mut n,2,x);}
    for p in &v.contrails{let mut x=Vec::new();x.extend(p.pos);x.extend(p.vel);x.extend([p.life,p.max_life,p.size,p.max_size,p.alpha,p.rotation]);x.extend(p.color.map(|v|v as f64));record(&mut o,&mut n,3,x);}
    for p in &v.debris{let mut x=Vec::new();x.extend(p.value.position);x.extend(p.value.velocity);x.extend([p.value.rotation,p.value.angular,p.value.size,p.value.life,p.max_life]);x.extend(p.value.color.map(|v|v as f64));x.extend([p.category as f64,p.value.texture as f64,flag(p.value.glowing)]);record(&mut o,&mut n,4,x);}
    for p in &v.explosions{if p.source.is_some()&&!p.source_field{return Err(8);}let mut x=vec![p.id,p.kind as f64];optional_string(&mut x,p.source.as_deref());x.push(flag(p.source_field));optional(&mut x,p.authored.map(flag));x.extend(p.position);x.extend([p.radius,p.max_radius,p.life,p.max_life,p.frame as f64,p.rotation]);x.extend(p.color.map(|v|v as f64));x.extend([flag(p.rings),p.shockwave,p.max_shockwave]);x.push(flag(p.puffs.is_some()));if let Some(p)=&p.puffs{x.push(p.len()as f64);for p in p{x.extend(p.offset);x.extend(p.velocity);x.extend([p.start,p.end,p.texture as f64,p.rotation]);}}optional(&mut x,p.puff_duration);
        x.push(flag(p.flash.is_some()));if let Some(p)=&p.flash{x.push(p.diameter);optional(&mut x,p.core);x.extend(p.color.map(|v|v as f64));x.push(p.duration);x.extend(p.velocity);}x.push(flag(p.flare.is_some()));if let Some(p)=&p.flare{x.extend([p.width,p.height]);x.extend(p.color.map(|v|v as f64));x.extend(p.velocity);}record(&mut o,&mut n,5,x);}
    for p in &v.glows{let p0=&p.value;let mut x=vec![p0.id];x.extend(p0.position);x.extend(p0.velocity);x.extend([p0.diameter,p0.life,p.max_life,p0.alpha]);x.extend(p.color.unwrap_or_else(||p0.color.map(|v|v as f64)));x.push(p0.custom as f64);record(&mut o,&mut n,6,x);}
    for p in &v.rays{let p0=&p.value;let mut x=vec![p0.id];x.extend(p0.head);x.extend(p0.tail);x.extend(p0.direction);x.extend([p0.speed,p0.life,p.max_life,p0.elapsed,p0.length,p0.width,p0.texture as f64,p0.scroll,p0.pixels]);x.extend(p0.fringe.map(|v|v as f64));x.extend(p0.core.map(|v|v as f64));record(&mut o,&mut n,7,x);}
    for p in &v.emp{let mut x=Vec::new();x.extend(p.from);x.extend(p.to);x.extend([p.life,p.max_life,p.thickness]);x.extend(p.core.map(|v|v as f64));x.extend(p.glow.map(|v|v as f64));points(&mut x,&p.segments);x.push(p.branches.len()as f64);for(points0,width)in &p.branches{points(&mut x,points0);x.push(*width);}x.push(flag(p.native.is_some()));if let Some(s)=&p.native{x.extend([s.anchor.slot as f64,s.anchor.generation as f64]);x.extend(s.local_from);x.extend(s.local_to);points(&mut x,&s.points);x.push(s.length);x.extend(s.fringe.map(|v|v as f64));x.extend(s.core.map(|v|v as f64));x.extend([s.period,s.elapsed,s.level,s.peak,s.brightness]);}record(&mut o,&mut n,8,x);}
    for p in &v.muzzles{let mut x=vec![p.id];optional_string(&mut x,p.owner.as_deref());optional_string(&mut x,p.spec.as_deref());x.extend(p.position);x.extend([p.angle,p.size]);x.extend(p.color.map(|v|v as f64));x.extend([p.life,p.max_life]);record(&mut o,&mut n,9,x);}
    for p in &v.muzzle_particles{let mut x=Vec::new();optional_string(&mut x,p.owner.as_deref());x.extend(p.position);x.extend(p.velocity);x.extend([p.size,p.life,p.max_life]);x.extend(p.color.map(|v|v as f64));optional(&mut x,p.normal.map(flag));record(&mut o,&mut n,10,x);}
    for p in &v.ripples{let mut x=Vec::new();x.extend(p.position);x.extend([p.radius,p.max_radius,p.life,p.max_life]);x.extend(p.color.map(|v|v as f64));record(&mut o,&mut n,11,x);}
    for p in &v.trails{let mut x=Vec::new();match &p.id{v::StripId::Number(id)=>x.extend([0.0,*id]),v::StripId::Text(id)=>{x.push(1.0);string(&mut x,id);}}x.extend(p.color.map(|v|v as f64));x.extend([flag(p.glow),p.widen,p.min_seg,flag(p.detached),p.accum,p.points.len()as f64]);for p in &p.points{x.extend(p.position);x.extend([p.age,p.duration,p.base_width,p.width,p.u,p.alpha]);}record(&mut o,&mut n,12,x);}
    for p in &v.ships{let b=bodies.iter().find(|b|b.handle==p.handle).ok_or(4u32)?;let mut x=vec![p.handle.slot as f64,p.handle.generation as f64,p.boost,p.previous_boost,p.ghosts.len()as f64];for g in &p.ghosts{x.extend(g.position);x.push(g.facing);}x.push(flag(p.surface.is_some()));if let Some((mode,level,progress))=p.surface{x.extend([mode as f64,level,progress]);}
        let levels=b.ship.as_ref().and_then(|s|s.shield.as_ref()).map(|s|s.visual_levels());x.push(flag(levels.is_some()));if let Some(l)=levels{x.push(l.len()as f64);x.extend(l.iter().map(|v|*v as f64));}record(&mut o,&mut n,13,x);}
    audio_records(&mut o,&mut n,v);
    if o.len()>8_000_000||o.iter().any(|v|!v.is_finite()){return Err(7);}o[1]=n as f64;Ok(o)}
